const rows = $input.all().map(i => i.json);
// Returning [] stops the chain, so a quiet day sends no email at all.
if (!rows.length) return [];

const byWf = {};
for (const r of rows) {
  const k = r.workflow_name || '(workflow sin nombre)';
  (byWf[k] = byWf[k] || []).push(r);
}

let body = `Errores de n8n en las ultimas 24 horas: ${rows.length}\n`;
body += `Workflows afectados: ${Object.keys(byWf).length}\n\n`;

for (const [wf, list] of Object.entries(byWf)) {
  body += `=== ${wf} — ${list.length} error(es) ===\n`;
  for (const r of list) {
    const t = new Date(r.occurred_at).toISOString().replace('T', ' ').slice(0, 16);
    body += `- ${t} UTC | nodo: ${r.node_name || '?'}\n`;
    body += `  ${String(r.error_message || '').slice(0, 400)}\n`;
    if (r.execution_url) body += `  ${r.execution_url}\n`;
  }
  body += '\n';
}

body += 'Nada que hacer si esto llega vacio: solo se envia cuando hubo al menos un error.\n';

return [{ json: { subject: `n8n: ${rows.length} error(es) en 24h`, body } }];
